import { DatePicker } from '@shared/components/custom/date-picker';
import {
  Button,
  Label,
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@shared/ui';
import { Filter, RotateCcw } from 'lucide-react';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

interface FilterValues {
  fromDate?: string;
  toDate?: string;
}

interface EmployeeAdjustmentFilterPopoverProps {
  filters: FilterValues;
  onApply: (filters: FilterValues) => void;
  onReset: () => void;
}

export function EmployeeAdjustmentFilterPopover({
  filters,
  onApply,
  onReset,
}: EmployeeAdjustmentFilterPopoverProps) {
  const { t } = useTranslation(['employeeAdjustment', 'common', 'action']);
  const [open, setOpen] = useState(false);
  const [localFilters, setLocalFilters] = useState<FilterValues>(filters);

  useEffect(() => {
    setLocalFilters(filters);
  }, [filters]);

  const handleApply = () => {
    onApply(localFilters);
    setOpen(false);
  };

  const handleReset = () => {
    setLocalFilters({});
    onReset();
    setOpen(false);
  };

  const activeCount = Object.values(filters).filter((v) => v !== undefined && v !== '').length;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className="h-9 gap-1.5 border-dashed text-xs">
          <Filter className="w-3.5 h-3.5" />
          <span>{t('employeeAdjustment:filter', { defaultValue: 'Bộ lọc' })}</span>
          {activeCount > 0 && (
            <span className="ml-1 rounded-full bg-primary text-primary-foreground text-[10px] w-4 h-4 flex items-center justify-center font-bold">
              {activeCount}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80 p-4 space-y-4" align="end">
        <div className="font-semibold text-sm border-b pb-2">
          {t('employeeAdjustment:filterByCreatedDate', { defaultValue: 'Bộ lọc theo ngày tạo' })}
        </div>

        <div className="space-y-3">
          {/* Từ ngày */}
          <div className="space-y-1">
            <Label className="text-xs">
              {t('employeeAdjustment:fromDate', { defaultValue: 'Từ ngày tạo' })}
            </Label>
            <DatePicker
              value={localFilters.fromDate ? new Date(localFilters.fromDate) : undefined}
              onChange={(date) =>
                setLocalFilters((prev) => ({
                  ...prev,
                  fromDate: date ? date.toISOString() : undefined,
                }))
              }
            />
          </div>

          {/* Đến ngày */}
          <div className="space-y-1">
            <Label className="text-xs">
              {t('employeeAdjustment:toDate', { defaultValue: 'Đến ngày tạo' })}
            </Label>
            <DatePicker
              value={localFilters.toDate ? new Date(localFilters.toDate) : undefined}
              onChange={(date) =>
                setLocalFilters((prev) => ({
                  ...prev,
                  toDate: date ? date.toISOString() : undefined,
                }))
              }
            />
          </div>
        </div>

        <div className="flex items-center justify-between border-t pt-3">
          <Button variant="ghost" size="sm" onClick={handleReset} className="h-8 gap-1 text-xs">
            <RotateCcw className="w-3.5 h-3.5" />
            <span>{t('action:reset', { defaultValue: 'Đặt lại' })}</span>
          </Button>
          <Button size="sm" onClick={handleApply} className="h-8 text-xs">
            {t('action:apply', { defaultValue: 'Áp dụng' })}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

