import { StepAndStatus } from '@/components/common/step-and-status';
import { Container } from '@/components/container';
import { PermissionEnum, PermissionModuleEn } from '@/enums/permission.enum';
import { EUploadType } from '@/enums/upload-type.enum';
import { useFile } from '@/hooks/use-file';
import { useTableChange } from '@/hooks/use-table-change';
import { toastError, toastSuccess } from '@/lib/toast';
import type {
  IEmployeeAdjustmentRequest,
  IEmployeeAdjustmentRequestParams,
} from '@/types/servicedesk/employee-adjustment.type';
import { WorkItemStatusEn } from '@shared/types';
import { CustomTable, ExportButton, PopConfirm } from '@shared/components';
import { ActionStack } from '@shared/components/custom/action-stack';
import DebouncedInput from '@shared/components/custom/debounce-input';
import { useHasPermission } from '@shared/permission';
import { Button, Checkbox, Tabs, TabsList, TabsTrigger } from '@shared/ui';
import { createFileRoute, useNavigate } from '@tanstack/react-router';
import type { ColumnDef } from '@tanstack/react-table';
import { zodValidator } from '@tanstack/zod-adapter';
import { format } from 'date-fns';
import { BarChart3, Eye, FileText, Layers, Loader2, Plus, SquarePen, Trash2 } from 'lucide-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { z } from 'zod';
import { EmployeeAdjustmentFilterPopover } from './-components/filter-popover';
import { EmployeeAdjustmentForm } from './-components/employee-adjustment-form';
import { BulkAdjustmentDialog } from './-components/bulk-adjustment-dialog';
import { AdjustmentReportTab } from './-components/adjustment-report-tab';
import { useEmployeeAdjustmentRequest } from '@/hooks/queries/use-employee-adjustment-request';
import { useGenerationCode } from '@/hooks/use-generation-code';

const AdjustmentSearchSchema = z.object({
  page: z.number().catch(1),
  pageSize: z.number().catch(10),
  sortBy: z.string().optional(),
  sortOrder: z.enum(['asc', 'desc']).optional(),
  code: z.string().optional(),
  name: z.string().optional(),
  statusCode: z.string().optional(),
  stepStatus: z.string().optional(),
  fromDate: z.string().optional(),
  toDate: z.string().optional(),
});

export const Route = createFileRoute('/_app/employee-adjustment/')({
  validateSearch: zodValidator(AdjustmentSearchSchema),
  component: EmployeeAdjustmentListPage,
});

function EmployeeAdjustmentListPage() {
  const { t } = useTranslation(['employeeAdjustment', 'common', 'action', 'message']);
  const navigate = useNavigate();
  const searchParams = Route.useSearch();
  const { downloadFile } = useFile();

  const [formOpen, setFormOpen] = useState(false);
  const [formMode, setFormMode] = useState<'create' | 'edit'>('create');
  const [selectedId, setSelectedId] = useState<string>('');
  const [isExporting, setIsExporting] = useState(false);
  const [currentTab, setCurrentTab] = useState<'requests' | 'report'>('requests');
  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);

  const canCreate = useHasPermission(
    PermissionModuleEn.EmployeeAdjustmentRequest,
    PermissionEnum.Create,
  );
  const canUpdate = useHasPermission(
    PermissionModuleEn.EmployeeAdjustmentRequest,
    PermissionEnum.Update,
  );
  const canDelete = useHasPermission(
    PermissionModuleEn.EmployeeAdjustmentRequest,
    PermissionEnum.Delete,
  );
  const canView = useHasPermission(
    PermissionModuleEn.EmployeeAdjustmentRequest,
    PermissionEnum.View,
  );
  const canExport = useHasPermission(
    PermissionModuleEn.EmployeeAdjustmentRequest,
    PermissionEnum.Export,
  );

  const { pagingQuery, deleteMutation, exportDataMutation, checkGenerationCodeQuery } = useEmployeeAdjustmentRequest({
    queryParam: {
      paging: {
        isEnable: true,
        params: searchParams,
        searchGroups: [
          {
            operator: 'OR',
            keys: ['code', 'reason'],
          },
        ],
        filterKeys: ['statusCode', 'stepStatus'],
        compares: [
          {
            key: 'createdDate',
            listKeysCompare: [
              { key: 'fromDate', operator: '>=' },
              { key: 'toDate', operator: '<=' },
            ],
          },
        ],
      },
      checkGenerationCode: {
        isEnable: true,
      },
    },
  });

  const { handleCheckAndProceed, isChecking, GenerationCodeDialogs } = useGenerationCode({
    checkGenerationCodeQuery,
    onProceed: () => {
      setSelectedId('');
      setFormMode('create');
      setFormOpen(true);
    },
  });

  const { updateFilters, handleSortingChange, handlePaginationChange, sorting } =
    useTableChange<IEmployeeAdjustmentRequestParams>({
      fullPath: Route.fullPath,
      searchData: searchParams,
      filterKeys: ['code'],
    });

  const handleExportData = async () => {
    if (!canExport) return;
    try {
      setIsExporting(true);
      const filePath = await exportDataMutation.mutateAsync();
      if (filePath) {
        await downloadFile({
          filePath,
          uploadType: EUploadType.Sftp,
        });
        toastSuccess(t('action:exportDataSuccess', { defaultValue: 'Xuất dữ liệu thành công' }));
      }
    } catch (error: any) {
      toastError(error?.message || t('message:error', { defaultValue: 'Có lỗi xảy ra khi xuất dữ liệu' }));
    } finally {
      setIsExporting(false);
    }
  };

  const columns: ColumnDef<IEmployeeAdjustmentRequest>[] = [
    {
      id: 'select',
      header: ({ table }) => (
        <Checkbox
          checked={
            table?.getIsAllPageRowsSelected?.() ||
            (table?.getIsSomePageRowsSelected?.() && 'indeterminate')
          }
          onCheckedChange={(value) => table?.toggleAllPageRowsSelected?.(!!value)}
          aria-label="Select all"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row?.getIsSelected?.() ?? false}
          onCheckedChange={(value) => row?.toggleSelected?.(!!value)}
          aria-label="Select row"
        />
      ),
      enableSorting: false,
      enableHiding: false,
      size: 40,
    },
    {
      id: 'index',
      header: () => <div className="text-center">{t('common:index', { defaultValue: 'STT' })}</div>,
      cell: ({ row }) => {
        const page = searchParams.page || 1;
        const pageSize = searchParams.pageSize || 10;
        return (
          <div className="text-center font-medium text-slate-500">
            {(page - 1) * pageSize + row.index + 1}
          </div>
        );
      },
      size: 50,
    },
    {
      accessorKey: 'code',
      header: t('employeeAdjustment:code', { defaultValue: 'Mã phiếu' }),
      cell: ({ row }) => (
        <span
          role="button"
          tabIndex={0}
          onClick={() =>
            navigate({
              to: '/employee-adjustment/$id',
              params: { id: row.original.id },
            })
          }
          className="font-medium text-foreground hover:underline cursor-pointer"
        >
          {row.original.code}
        </span>
      ),
      size: 110,
    },
    {
      id: 'employee',
      header: t('employeeAdjustment:employee', { defaultValue: 'Nhân viên' }),
      cell: ({ row }) => {
        const name = row.original.employee?.name || row.original.employeeNameSnapshot || t('common:notUpdated', { defaultValue: 'Chưa cập nhật' });
        const code = row.original.employee?.code || row.original.employeeCodeSnapshot || '';
        return (
          <div className="flex flex-col">
            <span className="font-medium text-slate-800 text-sm">{name}</span>
            {code ? (
              <span className="text-xs text-muted-foreground font-mono">{code}</span>
            ) : null}
          </div>
        );
      },
      size: 170,
    },
    {
      id: 'organization',
      header: t('employeeAdjustment:organization', { defaultValue: 'Phòng ban' }),
      cell: ({ row }) => {
        const orgName =
          row.original.organization?.name ||
          row.original.organizationNameSnapshot ||
          (row.original.employee as any)?.extraKeys?.organizationName ||
          row.original.employee?.organization?.name;
        return (
          <span className="text-sm text-slate-600">
            {orgName || t('common:notUpdated', { defaultValue: 'Chưa cập nhật' })}
          </span>
        );
      },
      size: 160,
    },
    {
      id: 'stepAndStatus',
      header: t('employeeAdjustment:stepAndStatus', { defaultValue: 'Trạng thái xử lý' }),
      cell: ({ row }) => {
        const info = row.original.workItemInfo;
        if (!info) return <span className="text-muted-foreground text-xs">{t('common:notUpdated', { defaultValue: 'Chưa cập nhật' })}</span>;
        return <StepAndStatus workItemInfo={info} />;
      },
      size: 170,
    },
    {
      accessorKey: 'effectiveDate',
      header: t('employeeAdjustment:effectiveDate', { defaultValue: 'Ngày hiệu lực' }),
      cell: ({ row }) => {
        const date = row.original.effectiveDate ? new Date(row.original.effectiveDate) : null;
        return (
          <span className="text-xs text-slate-600">{date ? format(date, 'dd/MM/yyyy') : t('common:notUpdated', { defaultValue: 'Chưa cập nhật' })}</span>
        );
      },
      size: 110,
    },
    {
      accessorKey: 'reason',
      header: t('employeeAdjustment:reason', { defaultValue: 'Lý do điều chỉnh' }),
      cell: ({ row }) => (
        <span className="text-xs text-slate-700 line-clamp-2" title={row.original.reason}>
          {row.original.reason || t('common:notUpdated', { defaultValue: 'Chưa cập nhật' })}
        </span>
      ),
      size: 220,
    },
    {
      accessorKey: 'createdDate',
      header: t('employeeAdjustment:createdDate', { defaultValue: 'Ngày tạo' }),
      cell: ({ row }) => {
        const date = row.original.createdDate ? new Date(row.original.createdDate) : null;
        return (
          <span className="text-xs text-slate-500">
            {date ? format(date, 'dd/MM/yyyy HH:mm') : t('common:notUpdated', { defaultValue: 'Chưa cập nhật' })}
          </span>
        );
      },
      size: 120,
    },
    {
      id: 'actions',
      header: () => <div className="text-center">{t('common:action', { defaultValue: 'Thao tác' })}</div>,
      cell: ({ row }) => {
        const info = row.original.workItemInfo;
        const isDraft = !info || info.statusEnum === WorkItemStatusEn.Draft;

        return (
          <div className="flex items-center justify-center gap-1">
            {canView && (
              <Button
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0 text-muted-foreground hover:text-foreground"
                onClick={() =>
                  navigate({
                    to: '/employee-adjustment/$id',
                    params: { id: row.original.id },
                  })
                }
                title={t('action:viewDetail', { defaultValue: 'Xem chi tiết' })}
              >
                <Eye className="h-4 w-4" />
              </Button>
            )}

            {canUpdate && (
              <Button
                variant="ghost"
                size="sm"
                disabled={!isDraft}
                className="h-8 w-8 p-0 text-primary hover:text-primary/80 disabled:opacity-30 disabled:cursor-not-allowed"
                onClick={() => {
                  if (!isDraft) return;
                  setSelectedId(row.original.id);
                  setFormMode('edit');
                  setFormOpen(true);
                }}
                title={isDraft ? t('action:edit', { defaultValue: 'Chỉnh sửa' }) : t('employeeAdjustment:editOnlyDraft', { defaultValue: 'Chỉ được chỉnh sửa khi phiếu ở trạng thái Dự thảo' })}
              >
                <SquarePen className="h-4 w-4" />
              </Button>
            )}

            {canDelete && (
              isDraft ? (
                <PopConfirm
                  variant="destructive"
                  confirmText={t('action:confirm', { defaultValue: 'Xác nhận' })}
                  description={t('employeeAdjustment:deleteConfirmDesc', {
                    defaultValue: `Bạn có chắc chắn muốn xóa phiếu "${row.original.code}"?`,
                    code: row.original.code,
                  })}
                  onConfirm={() => deleteMutation.mutate(row.original.id)}
                >
                  {(onClick) => (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0 text-destructive hover:text-destructive hover:bg-destructive/10"
                      onClick={onClick}
                      title={t('action:delete', { defaultValue: 'Xóa' })}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  )}
                </PopConfirm>
              ) : (
                <Button
                  variant="ghost"
                  size="sm"
                  disabled
                  className="h-8 w-8 p-0 text-destructive opacity-30 cursor-not-allowed"
                  title={t('employeeAdjustment:deleteOnlyDraft', { defaultValue: 'Chỉ được xóa khi phiếu ở trạng thái Dự thảo' })}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              )
            )}
          </div>
        );
      },
      size: 110,
    },
  ];

  return (
    <Container className="p-0 bg-transparent border-none rounded-none grid-rows-[1fr]">
      <div className="flex h-full min-h-0 min-w-0 flex-col gap-3 p-4">
        {/* ── Section 1: Header ── */}
        <div className="flex items-center justify-between gap-3 rounded-xl border bg-white px-4 py-3 shadow-sm shrink-0">
          <div className="text-xl font-bold">
            {t('employeeAdjustment:title', { defaultValue: 'Phiếu yêu cầu điều chỉnh thông tin nhân viên' })}
          </div>

          {currentTab === 'requests' && (
            <div className="flex items-center gap-2">
              {/* 1. Search */}
              <DebouncedInput
                value={searchParams.code || ''}
                onChange={(val) => updateFilters({ code: val as string, page: 1 })}
                placeholder={t('employeeAdjustment:searchPlaceholder', { defaultValue: 'Tìm theo mã, lý do...' })}
                className="w-56 h-9 text-xs"
              />

              {/* 2. Bộ lọc */}
              <EmployeeAdjustmentFilterPopover
                filters={{
                  fromDate: searchParams.fromDate,
                  toDate: searchParams.toDate,
                }}
                onApply={(f) => updateFilters({ ...f, page: 1 })}
                onReset={() =>
                  updateFilters({
                    fromDate: undefined,
                    toDate: undefined,
                    page: 1,
                  })
                }
              />

              {/* 3. Export, 4. Điều chỉnh hàng loạt, 5. Thêm */}
              <ActionStack
                actions={[
                  {
                    key: 'export',
                    hidden: !canExport,
                    element: (
                      <ExportButton
                        key="export-btn"
                        loading={exportDataMutation.isPending || isExporting}
                        onClick={handleExportData}
                        label={t('action:export', { defaultValue: 'Xuất Excel' })}
                        className="h-9 text-xs"
                      />
                    ),
                  },
                  {
                    key: 'bulk',
                    label: t('employeeAdjustment:bulkAdjustment', { defaultValue: 'Điều chỉnh hàng loạt' }),
                    icon: <Layers className="h-4 w-4 text-primary" />,
                    variant: 'outline',
                    onClick: () => setBulkDialogOpen(true),
                    hidden: !canCreate,
                    className: 'h-9 text-xs',
                  },
                  {
                    key: 'create',
                    label: t('action:add', { defaultValue: 'Thêm' }),
                    icon: isChecking ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Plus className="h-4 w-4" />
                    ),
                    variant: 'default',
                    onClick: handleCheckAndProceed,
                    loading: isChecking,
                    hidden: !canCreate,
                    className: 'h-9 text-xs',
                  },
                ]}
              />
            </div>
          )}
        </div>

        {/* ── Section 2: Tab Navigation ── */}
        <div className="flex items-center justify-between shrink-0">
          <Tabs
            value={currentTab}
            onValueChange={(val) => setCurrentTab(val as 'requests' | 'report')}
            className="shrink-0"
          >
            <TabsList className="h-9 p-1 bg-muted/60 border border-slate-200/80 rounded-xl shadow-2xs">
              <TabsTrigger
                value="requests"
                className="px-4 h-7 text-xs font-semibold rounded-lg data-[state=active]:bg-white! data-[state=active]:text-primary! data-[state=active]:shadow-xs! flex items-center gap-1.5 transition-all cursor-pointer"
              >
                <FileText className="w-3.5 h-3.5" />
                <span>
                  {t('employeeAdjustment:tabs.requests', { defaultValue: 'Danh sách phiếu yêu cầu' })}
                </span>
              </TabsTrigger>
              <TabsTrigger
                value="report"
                className="px-4 h-7 text-xs font-semibold rounded-lg data-[state=active]:bg-white! data-[state=active]:text-primary! data-[state=active]:shadow-xs! flex items-center gap-1.5 transition-all cursor-pointer"
              >
                <BarChart3 className="w-3.5 h-3.5" />
                <span>
                  {t('employeeAdjustment:tabs.report', { defaultValue: 'Báo cáo điều chỉnh trong kỳ' })}
                </span>
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>

        {/* ── Section 3: Table / Content ── */}
        {currentTab === 'requests' ? (
          <div className="flex-1 min-h-0 flex flex-col overflow-hidden">
            <CustomTable
              className="flex-1 min-h-0"
              tableId="employee-adjustment-requests-table"
              data={pagingQuery.data?.data || []}
              columns={columns}
              totalCount={pagingQuery.data?.totalCount}
              loading={pagingQuery.isLoading}
              enableRowSelection
              onPaginationChange={handlePaginationChange}
              onSortingChange={handleSortingChange}
              sorting={sorting}
              pagination={{
                pageIndex: (searchParams.page || 1) - 1,
                pageSize: searchParams.pageSize || 10,
              }}
              error={pagingQuery.error}
              onRetry={() => pagingQuery.refetch()}
            />
          </div>
        ) : (
          <div className="flex-1 min-h-0 flex flex-col overflow-hidden">
            <AdjustmentReportTab />
          </div>
        )}

        {/* Form Sheet */}
        <EmployeeAdjustmentForm
          open={formOpen}
          onOpenChange={setFormOpen}
          id={selectedId}
          mode={formMode}
        />

        {/* Bulk Adjustment Dialog */}
        <BulkAdjustmentDialog
          open={bulkDialogOpen}
          onOpenChange={setBulkDialogOpen}
          onSuccess={() => pagingQuery.refetch()}
        />

        {/* Generation Code Alert & Form Dialogs */}
        {GenerationCodeDialogs}
      </div>
    </Container>
  );
}

